const files = $input.all().map(i => i.json).filter(f => {
  const name = String(f.name || '');
  const isSheet = f.mimeType === 'application/vnd.google-apps.spreadsheet';
  return (isSheet || /\.xlsx?$/i.test(name)) && !name.startsWith('~$');
});
if (!files.length) throw new Error('No Excel file or Google Sheet matching the search term was found in the selected folder.');
// Prefer the date in the file name (e.g. Order_List_20261015.xlsx); files without a date come last
function dateFromName(name) {
  const m = String(name).match(/(20\d{2})[-_]?([01]\d)[-_]?([0-3]\d)/);
  if (!m) return -1;
  const t = Date.parse(m[1] + '-' + m[2] + '-' + m[3] + 'T00:00:00Z');
  return Number.isNaN(t) ? -1 : t;
}
files.sort((a, b) => dateFromName(b.name) - dateFromName(a.name));
const f = files[0];
return [{ json: { id: f.id, name: f.name, mimeType: f.mimeType || null } }];

// Map header names (English or Japanese) to fixed fields and stop on bad data
const HEADERS = {
  order_number: ['Order No.', 'Order Number', 'order_number', '受注番号', '注文番号'],
  customer_name: ['Customer', 'Customer Name', 'customer_name', '顧客名', '顧客'],
  product_name: ['Product', 'Product Name', 'product_name', '商品名', '案件名'],
  delivery_date: ['Due Date', 'Delivery Date', 'delivery_date', '納期', '納入日'],
};
const pick = (row, names) => {
  const key = Object.keys(row).find(k => names.includes(String(k).trim()));
  return key === undefined ? undefined : row[key];
};
function toIsoDate(v) {
  if (v === null || v === undefined || String(v).trim() === '') return '';
  const s = String(v).trim();
  if (/^\d+(\.\d+)?$/.test(s)) {
    const n = Number(s);
    if (n > 20000 && n < 80000) return new Date(Date.UTC(1899, 11, 30) + n * 86400000).toISOString().slice(0, 10);
  }
  const m = s.match(/^(\d{4})[\/\-年.](\d{1,2})[\/\-月.](\d{1,2})日?$/);
  if (m) return m[1] + '-' + m[2].padStart(2, '0') + '-' + m[3].padStart(2, '0');
  const d = new Date(s);
  if (!Number.isNaN(d.getTime())) return d.toISOString().slice(0, 10);
  throw new Error('Cannot parse due date: ' + s);
}
const rows = $input.all().map(i => i.json)
  .filter(r => Object.values(r).some(v => v !== null && v !== undefined && String(v).trim() !== ''));
if (!rows.length) throw new Error('The spreadsheet has no data rows.');
const out = rows.map((r, idx) => {
  const values = {};
  for (const [field, names] of Object.entries(HEADERS)) {
    const v = pick(r, names);
    if (v === undefined) throw new Error('Required column missing for ' + field + '. Accepted headers: ' + names.join(', '));
    values[field] = v;
  }
  const orderNumber = String(values.order_number ?? '').trim();
  if (!orderNumber) throw new Error('Order number is empty on data row ' + (idx + 2) + '.');
  return {
    order_number: orderNumber,
    customer_name: String(values.customer_name ?? '').trim(),
    product_name: String(values.product_name ?? '').trim(),
    delivery_date: toIsoDate(values.delivery_date),
  };
});
const seen = new Set();
for (const r of out) {
  if (seen.has(r.order_number)) throw new Error('Duplicate order number: ' + r.order_number);
  seen.add(r.order_number);
}
return out.map(json => ({ json }));

return [{ json: {
  mode: 'initialization',
  sourceFile: $('Pick Latest Order File').first().json.name,
  savedRows: $input.all().length,
  message: 'Baseline saved. Run the workflow again after the order list changes to detect new orders and due date changes.',
} }];

// Compares the current file with the baseline. The baseline is never modified here.
const current = $('Normalize and Validate Orders').all().map(i => i.json);
const baseline = new Map();
for (const r of $input.all().map(i => i.json)) {
  if (r.order_number) baseline.set(String(r.order_number), r);
}
const newOrders = [];
const dueDateChanges = [];
for (const c of current) {
  const old = baseline.get(c.order_number);
  if (!old) newOrders.push(c);
  else if (String(old.delivery_date ?? '') !== String(c.delivery_date ?? '')) {
    dueDateChanges.push({ ...c, previous_delivery_date: String(old.delivery_date ?? '') });
  }
}
const fmt = d => d || '(not set)';
const lines = ['Order change preview', 'New orders: ' + newOrders.length, 'Due date changes: ' + dueDateChanges.length, ''];
if (newOrders.length) {
  lines.push('== New orders ==');
  for (const r of newOrders) lines.push('Order: ' + r.order_number + '\nCustomer: ' + r.customer_name + '\nProduct: ' + r.product_name + '\nDue date: ' + fmt(r.delivery_date) + '\n');
}
if (dueDateChanges.length) {
  lines.push('== Due date changes ==');
  for (const r of dueDateChanges) lines.push('Order: ' + r.order_number + '\nCustomer: ' + r.customer_name + '\nProduct: ' + r.product_name + '\nBefore: ' + fmt(r.previous_delivery_date) + '\nAfter: ' + fmt(r.delivery_date) + '\n');
}
if (!newOrders.length && !dueDateChanges.length) lines.push('No new orders or due date changes.');
return [{ json: {
  mode: 'detection',
  sourceFile: $('Pick Latest Order File').first().json.name,
  newOrderCount: newOrders.length,
  dueDateChangeCount: dueDateChanges.length,
  preview: lines.join('\n'),
  newOrders,
  dueDateChanges,
} }];
